effect.shader:
float hash1(float n) {
    return fract(sin(n) * 43758.5453123) * 2.0 - 1.0;
}

float valueNoise(float x, float seed) {
    float i = floor(x);
    float f = fract(x);
    float u = f * f * (3.0 - 2.0 * f);
    return mix(hash1(i + seed), hash1(i + 1.0 + seed), u);
}

float lineNoise(float row, float t) {
    float sum = 0.0;
    float amp = 1.0 - lineSync;
    float space = 4.567 / detailZoom;
    float ts = 6.213;
    for (int i = 0; i < 6; i++) {
        sum += amp * valueNoise(row * space * 0.017 + t * ts, 17.0 + float(i) * 53.0);
        amp /= 2.71;
        space *= 2.231;
        ts *= 2.142;
    }
    return sum;
}

float interlaceMask(float y) {
    float p = mod(y, 10.0);
    float m = 1.0;
    if (p < 1.0) m = 0.8;
    else if (p < 5.0) m = 1.2;
    else if (p < 6.0) m = 0.8;
    else if (p < 7.0) m = 0.5;
    else if (p < 9.0) m = 0.2;
    else m = 0.5;
    return mix(1.0, m, interlacing);
}

vec3 grilleMask(float x) {
    float p = mod(x, 4.0);
    vec3 m;
    if (p < 1.0) m = mix(vec3(0.0), vec3(0.75,0.0,0.0), p);
    else if (p < 2.0) m = mix(vec3(0.75,0.0,0.0), vec3(0.0,0.75,0.0), p-1.0);
    else if (p < 3.0) m = mix(vec3(0.0,0.75,0.0), vec3(0.0,0.0,0.75), p-2.0);
    else m = mix(vec3(0.0,0.0,0.75), vec3(0.0), p-3.0);
    return m;
}

void main() {
    vec2 uv = acScreenNorm;
    vec2 centered = (uv - vec2(0.5)) / detailZoom + vec2(0.5);

    float verticalStrength = 1.0 - verticalSync;
    centered.y = fract(centered.y + verticalStrength * fract(acTime * 0.3333333 + 0.137));

    float row = centered.y * 1080.0;
    float jitterPx = lineNoise(row, acTime) * 22.0;
    centered.x += jitterPx / 1920.0;

    vec4 src = texture2D(inputImg.texture, centered);
    float a = src.a;
    vec3 straight = src.rgb / max(a, 0.0001);

    float scan = interlaceMask(row);
    if (scanPhasing > 0.0001) {
        float phase = fract(acTime * 3.0 * scanPhasing);
        float d = abs(centered.y - phase);
        d = min(d, 1.0 - d);
        float band = smoothstep(0.175, 0.0, d);
        scan *= mix(1.0, 2.5, band);
    }

    float grillePhase = acScreenNorm.x * 960.0 / detailZoom;
    vec3 g = grilleMask(grillePhase);
    float grain = statik * 0.5 * valueNoise(grillePhase * 0.5 + acTime * 23.0 + row * 0.17, 91.0);
    g = clamp(g + vec3(grain), 0.0, 1.0);

    float aperture = 0.75 * max(apertureGrill, statik);
    vec3 crt = mix(straight, 2.0 * straight * g + g * 0.25, aperture) * scan;

    float jitter = hash1(floor(acTime * 1000.0) + 131.0) * 0.05 * phosphorescence;
    vec3 gammaV = vec3(
        1.0 - 0.60 * phosphorescence + jitter,
        1.0 - 0.50 * phosphorescence + jitter,
        1.0 - 0.15 * phosphorescence + jitter
    );
    gammaV = clamp(gammaV, vec3(0.05), vec3(2.0));
    crt = pow(clamp(crt, 0.0, 1.0), gammaV);

    gl_FragColor = vec4(crt * a, a);
}
